import java.util.Scanner;

public class Solution {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        String entrada = in.nextLine();
        String[] placas = entrada.split(",");

        // Aplicar Radix Sort
        for (int i = 7; i > 3; i--) {
            placas = countingSort(placas, i);
        }

        // Imprimir as placas ordenadas
        StringBuilder out = new StringBuilder();
        for (String placa : placas) {
            out.append(placa).append(", ");
        }
        System.out.println(out.substring(0, out.length() - 2));
    }

    private static String[] countingSort(String[] arr, int index) {
        int[] count = new int[10];
        for (String s : arr) {
            count[s.charAt(index) - '0']++;
        }

        for (int i = 1; i < 10; i++) {
            count[i] += count[i - 1];
        }

        String[] output = new String[arr.length];
        for (int i = arr.length - 1; i >= 0; i--) {
            output[count[arr[i].charAt(index) - '0'] - 1] = arr[i];
            count[arr[i].charAt(index) - '0']--;
        }

        return output;
    }
}
```

