		int d1 = (int) (n % Math.pow(10, nthDig));
		d1 = (int) (d1 / Math.pow(10, nthDig - 1));

		int d2 = (int) (n % Math.pow(10, nthDig+1));
		d2 = (int) (d2 / Math.pow(10, nthDig));

		return Integer.valueOf(String.valueOf(d2) + String.valueOf(d1));
	}

