public class RadixSort {

    public static int[] countingSort(int[] arr, int k, int nthDig) {
        int[] count = new int[k];
        for (int num : arr) {
            int n = extractDigits(num, nthDig);
            count[n]++;
        }

        for (int i = 1; i < count.length; i++) {
