import java.util.Arrays;
import java.util.Scanner;

public class RadixSort {

    // Função para extrair o par de dígitos de um número na posição especificada
    public static int extractDigits(int n, int position) {
        int d1 = (n / (int) Math.pow(10, position - 1)) % 10;
        int d2 = (n / (int) Math.pow(10, position)) % 10;
        return d2 * 10 + d1; // Concatenar os dígitos na ordem certa
    }

    // Implementação do Counting Sort para ordenar com base nos pares de dígitos
    public static int[] countingSort(int[] arr, int k, int position) {
        int[] count = new int[k + 1]; // Considerando 0 como índice válido
        int[] output = new int[arr.length];

        // Contar a frequência de cada par de dígitos
        for (int num : arr) {
            int index = extractDigits(num, position);
            count[index]++;
        }

        // Calcular a soma cumulativa
        for (int i = 1; i <= k; i++) {
            count[i] += count[i - 1];
        }

        // Construir o array de saída
        for (int i = arr.length - 1; i >= 0; i--) {
            int index = extractDigits(arr[i], position);
            output[count[index] - 1] = arr[i];
            count[index]--;
        }

        return output;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String[] entrada = sc.nextLine().split(" ");
        int[] arr = new int[entrada.length];
