        }

        int d = Integer.parseInt(sc.nextLine()); // Número de dígitos

        // Iterar sobre os pares de dígitos, começando do menos significativo
        for (int i = 1; i <= d; i += 2) {
            arr = countingSort(arr, 99, i); // 99 é o valor máximo para o par de dígitos
            System.out.println(Arrays.toString(arr));
        }

        sc.close();
    }
}
