        Node node = search(n);
        if (node == null) return;

        if (node.right != null) {
            l.add(node.value);
            min(node.right, l); 
        } else {

            Node aux = node;
            while (aux.parent != null && aux.parent.value < n) {
                l.add(aux.value);
                aux = aux.parent;
            }

            l.add(aux.value);
            if (aux.parent == null)
                l.add(aux.parent.value);

        }
    }



