		int menoresI = 0;
		for (int k = 0; k < array.length; k++) {
			if (array[k] < array[i])
				menoresI +=1;
		}

		int menoresJ = 0;
		for (int k = 0; k < array.length; k++) {
			if (array[k] < array[j])
				menoresJ +=1;
		}

		int med = array.length / 2;

		if (Math.abs(menoresI - med) < Math.abs(menoresJ - med))
			return i;
		else
			return j;

	}

	private static int particiona(int[] array, int i) {
		swap(array,0,i);
		int pivot = array[0];
		int index_pivot = 0;

		for (int j = 1; j < array.length; j++) {
