        int j = meio + 1;
        int k = ini;

        while (i <= meio && j <= fim) {
            if (helper[i] < helper[j])
                v[k++] = helper[i++]; 
            else
                v[k++] = helper[j++];

        }

        while (i <= meio)
            v[k++] = helper[i++];

        while (j <= fim)
            v[k++] = helper[j++];

    }
