    public void add(int value) {
        Node newNode = new Node(value);
        if (isEmpty()) {
            head = newNode;
            tail = newNode;
        } else {
            tail.next = newNode;
            newNode.prev = tail;
            tail = newNode;
        }
        size++;
    }

    // Remove an element from the front of the queue (head)
    public boolean remove() {
        if (isEmpty()) return false;
        head = head.next;
        if (head == null) tail = null;
        else head.prev = null;
        size--;
        return true;
    }

