import java.util.*;

class Node {
    int value;
    Node left, right;
    Node(int value) {
        this.value = value;
        this.left = this.right = null;
    }
    // Método para adicionar um nó à BST
    void add(int value) {
        if (value < this.value) {
            if (this.left == null) this.left = new Node(value);
            else this.left.add(value);
        } else {
