class BST {
    Node root;
    BST() { this.root = null; }
    void add(int value) {
        if (root == null) root = new Node(value);
        else root.add(value);
    }
    // Método para realizar BFS da direita para a esquerda
    void bfsRightToLeft() {
        if (root == null) return;
        Queue<Node> queue = new LinkedList<>();
        queue.add(root);
        while (!queue.isEmpty()) {
            int size = queue.size();
            Stack<Node> stack = new Stack<>();
            for (int i = 0; i < size; i++) {
                Node node = queue.poll();
                stack.push(node);
                if (node.left != null) queue.add(node.left);
                if (node.right != null) queue.add(node.right);
            }
            while (!stack.isEmpty()) {
                System.out.print(stack.pop().value + " ");
            }
        }
    }
}

